<script setup lang="ts">
import {onUnmounted,ref,watch} from 'vue'
import {api,displayText,label,time} from '../api'
import type {DeviceAnalysisContext,EvidenceSnapshot} from '../evidence'
import Icon from './Icon.vue'
const props=defineProps<{deviceId:string;sourceView:'overview'|'map'|'coordination';imageId:string|null}>()
const emit=defineEmits<{'open-evidence':[snapshot:EvidenceSnapshot];'select-event':[id:string]}>()
const context=ref<DeviceAnalysisContext|null>(null),incidentId=ref(''),loading=ref(false),busy=ref(false),error=ref('')
let generation=0
async function load(selected?:string){const token=++generation;loading.value=true;error.value='';try{const result=await api<DeviceAnalysisContext>(`/devices/${encodeURIComponent(props.deviceId)}/analysis-context${selected?'?incident_id='+encodeURIComponent(selected):''}`);if(token!==generation)return;context.value=result;incidentId.value=result.selected_incident_id||''}catch(e){if(token===generation)error.value=(e as Error).message}finally{if(token===generation)loading.value=false}}
async function analyze(){if(!context.value?.can_analyze||context.value.selected_incident_id!==incidentId.value||!incidentId.value||busy.value)return;const token=generation,deviceId=props.deviceId,id=incidentId.value;busy.value=true;error.value='';try{const snapshot=await api<EvidenceSnapshot>(`/incidents/${encodeURIComponent(id)}/evidence-snapshots`,{source_view:props.sourceView,image_id:props.imageId,source_selection:{kind:'device',id:deviceId}});if(token===generation)emit('open-evidence',snapshot)}catch(e){if(token===generation)error.value=(e as Error).message}finally{if(token===generation)busy.value=false}}
watch(()=>props.deviceId,()=>{context.value=null;incidentId.value='';busy.value=false;void load()},{immediate:true})
onUnmounted(()=>generation++)
</script>
<template><section class="device-analysis"><h4>关联事件与 Agent 核查</h4><p v-if="loading" class="panel-hint" role="status">正在核对设备与事件关联…</p><div v-if="error" class="evidence-error" role="alert">{{displayText(error)}}<button class="text-button" :disabled="busy" @click="load(incidentId||undefined)">重试关联查询</button></div><template v-if="context"><button v-for="event in context.related_incidents.filter(item=>item.code==='EVT-008')" :key="event.id" class="outline-button" :disabled="busy||loading" @click="load(event.id)">选择 EVT-008 温度异常事件</button><label class="device-event-select">选择本次核查事件<select v-model="incidentId" aria-label="设备关联核查事件" :disabled="busy||loading" @change="load(incidentId||undefined)"><option value="">{{context.related_incidents.length?'请选择关联事件':'暂无关联事件'}}</option><option v-for="event in context.related_incidents" :key="event.id" :value="event.id">{{event.code||'历史事件'}} · {{displayText(event.title)}} · {{time(event.triggered_at,true)}}</option></select></label><p class="panel-hint">{{displayText(context.reason||'核查只使用所选事件证据；设备当前读数可能来自另一事件。')}}</p><div class="device-analysis-actions"><button class="outline-button" :disabled="!incidentId||busy||loading" @click="emit('select-event',incidentId)">查看关联事件详情</button><button class="primary-button" :disabled="busy||loading||!context.can_analyze||context.selected_incident_id!==incidentId||!incidentId" @click="analyze"><Icon name="spark" :size="15"/>{{busy?'正在保存证据…':'Agent 分析所选事件'}}</button></div></template><p v-if="!loading&&!context&&!error" class="panel-hint">设备关联上下文暂不可用。</p></section></template>
